const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => Array.from(document.querySelectorAll(selector));
const money = (amount) => new Intl.NumberFormat("vi-VN").format(amount) + "đ";

let category = "all";
let searchText = "";
let cart = readStorage("foodflow_cart", []);
let favorites = readStorage("foodflow_favorites", []);
let user = readStorage("foodflow_user", null) || readSession("foodflow_user", null);
let toastTimer;

function readStorage(key, fallback) {
  try { const value = localStorage.getItem(key); return value ? JSON.parse(value) : fallback; }
  catch { return fallback; }
}
function readSession(key, fallback) {
  try { const value = sessionStorage.getItem(key); return value ? JSON.parse(value) : fallback; }
  catch { return fallback; }
}
function toast(message) {
  const box = $("#toast");
  if (!box) return;
  box.textContent = message;
  box.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => box.classList.remove("show"), 2600);
}
function setUserLabel() {
  $("#headerUser").textContent = user ? user.name.split(" ")[0] : "Đăng nhập";
}
function setAuthTab(tab) {
  $$("[data-auth-tab]").forEach(button => button.classList.toggle("active", button.dataset.authTab === tab));
  $("#loginForm").classList.toggle("hidden", tab !== "login");
  $("#registerForm").classList.toggle("hidden", tab !== "register");
  $("#authTitle").textContent = tab === "login" ? "Đăng nhập để đặt món" : "Tạo tài khoản FoodFlow";
}
function openAuth(tab = "login") {
  $("#authModal").classList.remove("hidden");
  setAuthTab(tab);
}
function closeAuth() { $("#authModal").classList.add("hidden"); }
function requireLogin() {
  if (user) return true;
  openAuth("login");
  toast("Bạn cần đăng nhập hoặc tạo tài khoản trước khi đặt món.");
  return false;
}
function setCategory(nextCategory) {
  category = nextCategory;
  $$(".category-chip").forEach(button => button.classList.toggle("selected", button.dataset.category === category));
  renderFoods();
}
function renderFoods() {
  const query = searchText.trim().toLocaleLowerCase("vi");
  let list = foods.filter(food => {
    const categoryMatches =
      category === "all" ||
      (category === "savory" && ["rice", "noodle", "snack"].includes(food.category)) ||
      food.category === category;
    const searchMatches = !query || `${food.name} ${food.restaurant} ${food.description}`.toLocaleLowerCase("vi").includes(query);
    return categoryMatches && searchMatches;
  });

  const sort = $("#sortSelect").value;
  if (sort === "low") list.sort((a, b) => a.price - b.price);
  if (sort === "high") list.sort((a, b) => b.price - a.price);

  if (category === "drink") $("#menuTitle").textContent = "Đồ uống mát lạnh 🧋";
  else if (category === "vegetarian") $("#menuTitle").textContent = "Món chay thanh lành 🌿";
  else if (category === "all") $("#menuTitle").textContent = "Món ngon được yêu thích ✦";
  else $("#menuTitle").textContent = "Khám phá thực đơn ✦";

  $("#menuSubtitle").textContent = `Tổng cộng ${foods.length} món ăn và đồ uống để bạn lựa chọn`;
  $("#filterNote").textContent = `Đang hiển thị ${list.length} món${searchText ? ` phù hợp với “${searchText}”` : ""}.`;
  $("#filterNote").classList.toggle("hidden", category === "all" && !searchText);

  $("#foodGrid").innerHTML = list.map(food => `
    <article class="food-card">
      <div class="food-image">
        <img loading="lazy" src="${food.img}" alt="${food.name}"
          onerror="this.onerror=null;this.src='https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80'">
        ${food.badge ? `<span class="badge ${food.category === "vegetarian" ? "veg" : ""}">${food.badge}</span>` : ""}
        <button class="favorite ${favorites.includes(food.id) ? "liked" : ""}" data-favorite="${food.id}" aria-label="Lưu món yêu thích">${favorites.includes(food.id) ? "♥" : "♡"}</button>
      </div>
      <div class="food-info">
        <h3>${food.name}</h3>
        <p class="restaurant">${food.restaurant}</p>
        <p class="description">${food.description}</p>
        <div class="food-meta"><span>★ ${food.rating.toFixed(1)}</span><strong>${money(food.price)}</strong></div>
        <button class="add-btn" data-add="${food.id}">＋ Thêm vào giỏ</button>
      </div>
    </article>`).join("");

  $("#emptyState").classList.toggle("hidden", list.length > 0);
  $("#foodGrid").classList.toggle("hidden", list.length === 0);
}
function saveCart() {
  localStorage.setItem("foodflow_cart", JSON.stringify(cart));
  $("#cartCount").textContent = cart.reduce((sum, item) => sum + item.qty, 0);
}
function addToCart(id) {
  if (!requireLogin()) return;
  const existing = cart.find(item => item.id === id);
  if (existing) existing.qty += 1;
  else cart.push({ id, qty: 1 });
  saveCart();
  toast("Đã thêm món vào giỏ hàng!");
}
function renderCart() {
  cart = cart.filter(item => foods.some(food => food.id === item.id) && item.qty > 0);
  const count = cart.reduce((sum, item) => sum + item.qty, 0);
  const subtotal = cart.reduce((sum, item) => sum + foods.find(food => food.id === item.id).price * item.qty, 0);
  const delivery = subtotal ? 15000 : 0;
  $("#cartTitleCount").textContent = `(${count} món)`;
  $("#cartSubtotal").textContent = money(subtotal);
  $("#deliveryFee").textContent = money(delivery);
  $("#cartTotal").textContent = money(subtotal + delivery);

  $("#cartItems").innerHTML = cart.length ? cart.map(item => {
    const food = foods.find(entry => entry.id === item.id);
    return `<div class="cart-item">
      <img src="${food.img}" alt="${food.name}">
      <div><b>${food.name}</b><small>${money(food.price)}</small>
      <div class="qty"><button data-qty="${food.id}" data-change="-1" aria-label="Giảm">−</button> ${item.qty}
      <button data-qty="${food.id}" data-change="1" aria-label="Tăng">＋</button></div></div>
      <strong>${money(food.price * item.qty)}</strong>
    </div>`;
  }).join("") : '<p class="empty-cart">Giỏ hàng đang trống. Hãy chọn món ngon nhé!</p>';
  saveCart();
}
function getAccounts() { return readStorage("foodflow_accounts", []); }
function persistUser(nextUser, remember) {
  user = nextUser;
  localStorage.removeItem("foodflow_user");
  sessionStorage.removeItem("foodflow_user");
  (remember ? localStorage : sessionStorage).setItem("foodflow_user", JSON.stringify(user));
  setUserLabel();
}

/* Chọn danh mục và tìm kiếm */
$("#categoryList").addEventListener("click", event => {
  const button = event.target.closest("[data-category]");
  if (button) {
    setCategory(button.dataset.category);
    $("#menu").scrollIntoView({ behavior: "smooth" });
  }
});
$("#foodGrid").addEventListener("click", event => {
  const addButton = event.target.closest("[data-add]");
  const favoriteButton = event.target.closest("[data-favorite]");
  if (addButton) addToCart(Number(addButton.dataset.add));
  if (favoriteButton) {
    if (!requireLogin()) return;
    const id = Number(favoriteButton.dataset.favorite);
    favorites = favorites.includes(id) ? favorites.filter(value => value !== id) : [...favorites, id];
    localStorage.setItem("foodflow_favorites", JSON.stringify(favorites));
    renderFoods();
  }
});
$("#sortSelect").addEventListener("change", renderFoods);
$("#headerSearch").addEventListener("input", event => {
  searchText = event.target.value;
  $("#heroSearch").value = searchText;
  renderFoods();
});
$("#heroSearchForm").addEventListener("submit", event => {
  event.preventDefault();
  searchText = $("#heroSearch").value;
  $("#headerSearch").value = searchText;
  renderFoods();
  $("#menu").scrollIntoView({ behavior: "smooth" });
});
$("#resetFilters").addEventListener("click", () => {
  searchText = "";
  $("#headerSearch").value = "";
  $("#heroSearch").value = "";
  setCategory("all");
});
$$("[data-category-link]").forEach(link => link.addEventListener("click", () => setCategory(link.dataset.categoryLink)));
$("#exploreVeg").addEventListener("click", () => {
  setCategory("vegetarian");
  $("#menu").scrollIntoView({ behavior: "smooth" });
});

/* Đăng nhập và đăng ký */
$("#openAuth").addEventListener("click", () => user ? toast(`Bạn đã đăng nhập: ${user.email}`) : openAuth());
$("#closeAuth").addEventListener("click", closeAuth);
$("#authModal").addEventListener("click", event => { if (event.target.id === "authModal") closeAuth(); });
$$("[data-auth-tab]").forEach(button => button.addEventListener("click", () => setAuthTab(button.dataset.authTab)));
$$("[data-switch-auth]").forEach(button => button.addEventListener("click", () => setAuthTab(button.dataset.switchAuth)));

$("#loginForm").addEventListener("submit", event => {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  const email = String(data.get("email")).trim().toLowerCase();
  const password = String(data.get("password"));
  const account = getAccounts().find(entry => entry.email === email && entry.password === password);
  if (!account) { toast("Email hoặc mật khẩu chưa đúng."); return; }
  persistUser({ name: account.name, email: account.email }, data.get("remember") === "on");
  closeAuth();
  event.currentTarget.reset();
  toast(`Xin chào ${account.name}!`);
});
$("#registerForm").addEventListener("submit", event => {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  const name = String(data.get("name")).trim();
  const email = String(data.get("email")).trim().toLowerCase();
  const password = String(data.get("password"));
  if (password !== String(data.get("confirmPassword"))) { toast("Mật khẩu nhập lại chưa khớp."); return; }
  const accounts = getAccounts();
  if (accounts.some(entry => entry.email === email)) { toast("Email này đã được đăng ký."); return; }
  accounts.push({ name, email, password });
  localStorage.setItem("foodflow_accounts", JSON.stringify(accounts));
  persistUser({ name, email }, true);
  closeAuth();
  event.currentTarget.reset();
  toast("Tạo tài khoản thành công!");
});

/* Giỏ hàng */
$("#cartButton").addEventListener("click", () => {
  $("#cartModal").classList.remove("hidden");
  renderCart();
});
$("#closeCart").addEventListener("click", () => $("#cartModal").classList.add("hidden"));
$("#cartModal").addEventListener("click", event => {
  if (event.target.id === "cartModal") $("#cartModal").classList.add("hidden");
});
$("#cartItems").addEventListener("click", event => {
  const button = event.target.closest("[data-qty]");
  if (!button) return;
  const item = cart.find(entry => entry.id === Number(button.dataset.qty));
  if (item) item.qty += Number(button.dataset.change);
  cart = cart.filter(entry => entry.qty > 0);
  renderCart();
});
$("#checkoutButton").addEventListener("click", () => {
  if (!cart.length) { toast("Giỏ hàng đang trống."); return; }
  if (!requireLogin()) return;
  toast("Đây là bản demo học tập; cần máy chủ để xác nhận đơn hàng thật.");
});
$("#mobileMenu").addEventListener("click", () => $("#navLinks").classList.toggle("open"));
$("#navLinks").addEventListener("click", event => {
  if (event.target.closest("a")) $("#navLinks").classList.remove("open");
});
document.addEventListener("keydown", event => {
  if (event.key === "Escape") {
    closeAuth();
    $("#cartModal").classList.add("hidden");
  }
});

renderFoods();
saveCart();
setUserLabel();
